'use client'
import type { FormEvent, Ref } from 'react'
import { Button } from '@/components/ui/Button'
import { useControllable } from '@/hooks/useControllable'
import { cn } from '@/lib/cn'

// The ad's search bar: a Black field with the brand corner (88px tall on the canvas, 56px here), the prompt in White
// DM Sans and a White "Search" button inside it, 8px in (16px on the canvas). A #666666 hairline lets it read on Black
// and turns White while the field has focus. Enter or the button calls onSearch with the query; the value is
// controlled (value + onValueChange) or kept inside (defaultValue).
export interface SearchBarProps {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** The query, when Enter is pressed or the button clicked. */
  onSearch?: (query: string) => void
  placeholder?: string
  /** The button's label. */
  buttonLabel?: string
  /** The field's accessible name (the placeholder is not one). */
  label?: string
  name?: string
  disabled?: boolean
  className?: string
  ref?: Ref<HTMLFormElement>
}

export function SearchBar({ value, defaultValue = '', onValueChange, onSearch, placeholder = 'Search creatives', buttonLabel = 'Search', label = 'Search', name = 'q', disabled, className, ref }: SearchBarProps) {
  const [query, setQuery] = useControllable(value, defaultValue, onValueChange)
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!disabled) onSearch?.(query)
  }
  return (
    <form data-ds="search-bar" ref={ref} role="search" onSubmit={submit} className={cn('flex h-search w-full items-center gap-2 rounded-control border border-edge-strong bg-surface pr-2 pl-4 transition-[border-color] duration-160 ease-standard has-[input:focus-visible]:border-edge-focus', className)}>
      <input
        type="search"
        name={name}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder={placeholder}
        aria-label={label}
        disabled={disabled}
        autoComplete="off"
        className="h-full min-w-0 flex-1 bg-transparent type-body text-fg outline-none placeholder:text-fg-muted disabled:cursor-not-allowed [&::-webkit-search-cancel-button]:hidden"
      />
      <Button type="submit" disabled={disabled}>{buttonLabel}</Button>
    </form>
  )
}

export default SearchBar

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
